// Parse Telegram command
const message = $input.first().json.message;
const text = message.text || '';
const chatId = message.chat.id;
const username = message.from.username || message.from.first_name || 'Bosku';

const cleanText = text.trim();
const parts = cleanText.split(' ');
const rawCommand = parts[0].replace('/', '').toLowerCase().split('@')[0];
const args = parts.slice(1);

return {
  json: {
    command: rawCommand,
    args: args,
    chatId: chatId,
    username: username,
    fullText: text,
    timestamp: new Date().toISOString()
  }
};

const args = $input.first().json.args;
const chatId = $input.first().json.chatId;
const symbol = (args[0] || 'BBCA').toUpperCase().trim();

return {
  json: {
    symbol: symbol,
    chatId: chatId
  }
};

